      execSync('git config user.email "clone@test.com"', { cwd: cloneDir, stdio: 'pipe' });
      execSync('git config user.name "Clone"', { cwd: cloneDir, stdio: 'pipe' });
      execSync(`git worktree add .kspec ${SHADOW_BRANCH_NAME}`, { cwd: cloneDir, stdio: 'pipe' });

      // Modify a file in the clone's shadow and push
      const tasksFile = (await fs.readdir(path.join(cloneDir, '.kspec')))
        .find(f => f.endsWith('.tasks.yaml'));
      if (tasksFile) {
        await fs.appendFile(
          path.join(cloneDir, '.kspec', tasksFile),
          '\n# Clone change for bidir test\n'
        );
        execSync('git add -A && git commit -m "Clone change"', {
          cwd: path.join(cloneDir, '.kspec'),
          stdio: 'pipe',
        });
        execSync(`git push origin ${SHADOW_BRANCH_NAME}`, {
          cwd: path.join(cloneDir, '.kspec'),
          stdio: 'pipe',
        });
      }

      // Now make a LOCAL change and use shadowPushAsync (which should pull-rebase first)
      const localTasksFile = (await fs.readdir(worktreeDir))
        .find(f => f.endsWith('.tasks.yaml'));
      if (localTasksFile) {
        await fs.appendFile(
          path.join(worktreeDir, localTasksFile),
          '\n# Local change for bidir test\n'
        );
        await shadowAutoCommit(worktreeDir, 'Local bidir change');
      }

      // Push — should pull-rebase then push
      await shadowPushAsync(worktreeDir);

      // Verify both changes are present locally (pull-rebase integrated remote)
      const localContent = await fs.readFile(
        path.join(worktreeDir, localTasksFile!),
        'utf-8',
      );
      expect(localContent).toContain('# Clone change for bidir test');
      expect(localContent).toContain('# Local change for bidir test');

      // Verify remote has both changes too
      const verifyDir = path.join('/tmp', `kspec-bidir-verify-${Date.now()}`);
      try {
        execSync(`git clone ${remoteDir} ${verifyDir}`, { stdio: 'pipe' });
        execSync(`git -C ${verifyDir} checkout ${SHADOW_BRANCH_NAME}`, { stdio: 'pipe' });
        const remoteContent = await fs.readFile(
          path.join(verifyDir, localTasksFile!),
          'utf-8',
        );
        expect(remoteContent).toContain('# Clone change for bidir test');
        expect(remoteContent).toContain('# Local change for bidir test');
      } finally {
        await fs.rm(verifyDir, { recursive: true, force: true });
      }
    } finally {
      await fs.rm(cloneDir, { recursive: true, force: true });
    }
  });

