    execSync('git config user.email "clone@test.com"', { cwd: cloneDir, stdio: 'pipe' });
    execSync('git config user.name "Clone"', { cwd: cloneDir, stdio: 'pipe' });
    execSync(`git worktree add .kspec ${SHADOW_BRANCH_NAME}`, { cwd: cloneDir, stdio: 'pipe' });

    // Find the manifest file and create a conflicting change
    const manifestFile = (await fs.readdir(path.join(cloneDir, '.kspec')))
      .find(f => f.endsWith('.yaml') && !f.includes('.tasks.') && !f.includes('.inbox.') && !f.includes('.gitattributes') && !f.includes('.gitignore'));

    if (manifestFile) {
      // Remote: modify the same line
      await fs.writeFile(
        path.join(cloneDir, '.kspec', manifestFile),
        'kynetic: "2.0"\nproject:\n  name: "Remote Version"\n  version: "1.0.0"\n  status: active\n'
      );
      execSync('git add -A && git commit -m "Remote rewrite"', {
        cwd: path.join(cloneDir, '.kspec'),
        stdio: 'pipe',
      });
      execSync(`git push origin ${SHADOW_BRANCH_NAME}`, {
        cwd: path.join(cloneDir, '.kspec'),
        stdio: 'pipe',
      });

      // Local: ALSO rewrite the manifest (different content on same lines → conflict)
      await fs.writeFile(
        path.join(worktreeDir, manifestFile),
        'kynetic: "3.0"\nproject:\n  name: "Local Version"\n  version: "2.0.0"\n  status: draft\n'
      );
      await shadowAutoCommit(worktreeDir, 'Local rewrite');

      // Suppress warning output
      const consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
      try {
        // Push should fail gracefully because pull-rebase conflict
        await shadowPushAsync(worktreeDir);

        // Should see a push failure warning about conflicts
        expect(consoleErrorSpy).toHaveBeenCalledWith(
          expect.stringContaining('[WARN] Shadow auto-push failed')
        );
      } finally {
        consoleErrorSpy.mockRestore();
      }
    }
  } finally {
    await fs.rm(cloneDir, { recursive: true, force: true });
  }
});

